-- ─── 3. payment.order_id holds the order's external UUID, not orders.id ─────────
-- Payment.orderId is a UUID; the baseline created a BIGINT column with a foreign key to orders(id).

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_schema = current_schema() AND table_name = 'payment'
                 AND column_name = 'order_id' AND udt_name = 'int8') THEN
        IF EXISTS (SELECT 1 FROM payment WHERE order_id IS NOT NULL) THEN
            RAISE EXCEPTION 'payment.order_id holds BIGINT values; they cannot be converted to order UUIDs automatically';
        END IF;
        ALTER TABLE payment DROP CONSTRAINT IF EXISTS payment_order_id_fkey;
        ALTER TABLE payment ALTER COLUMN order_id TYPE UUID USING NULL;
    END IF;
END $$;

-- ─── 4. agreements is keyed by agreement_id (Agreement's @Id) ───────────────────

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_index i
               JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = ANY (i.indkey)
               WHERE i.indrelid = 'agreements'::regclass AND i.indisprimary AND a.attname = 'id') THEN
        ALTER TABLE user_agreements DROP CONSTRAINT IF EXISTS user_agreements_agreement_id_fkey;
        ALTER TABLE agreements DROP CONSTRAINT agreements_pkey;
        ALTER TABLE agreements ADD CONSTRAINT agreements_pkey PRIMARY KEY (agreement_id);
        ALTER TABLE user_agreements ADD CONSTRAINT user_agreements_agreement_id_fkey
            FOREIGN KEY (agreement_id) REFERENCES agreements (agreement_id);
    END IF;
END $$;

-- ─── 5. users.gender CHECK predates the Gender enum ─────────────────────────────
-- chk_users_gender (from a deleted migration) allows MALE, FEMALE, UNKNOWN and OTHER: it rejects
-- Gender.PREFER_NOT_TO_SAY and accepts two values the enum cannot read. Enum columns carry no CHECK
-- in this schema, so it is dropped rather than rewritten.

ALTER TABLE users DROP CONSTRAINT IF EXISTS chk_users_gender;

-- ─── 6. Legacy baseline columns no entity writes: allow NULL so inserts succeed ──

DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN SELECT * FROM (VALUES
        ('agreements', 'type'),
        ('chat_messages', 'chat_room_id'),
        ('chat_messages', 'sender_id'),
        ('chat_rooms', 'user_id_1'),
        ('chat_rooms', 'user_id_2'),
        ('offers', 'price'),
        ('seller_follows', 'seller_id')
    ) AS v(table_name, column_name) LOOP
        IF EXISTS (SELECT 1 FROM information_schema.columns
                   WHERE table_schema = current_schema() AND table_name = r.table_name
                     AND column_name = r.column_name AND is_nullable = 'NO') THEN
            EXECUTE format('ALTER TABLE %I ALTER COLUMN %I DROP NOT NULL', r.table_name, r.column_name);
        END IF;
    END LOOP;
END $$;

-- ─── 7. Foreign key, unique and check constraints of the running schema ──────

DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN SELECT * FROM (VALUES
        ('inventory', 'chk_inventory_available_quantity_non_negative', 'CHECK ((available_quantity >= 0))'),
        ('campaign_eligible_listings', 'campaign_eligible_listings_listing_id_fkey', 'FOREIGN KEY (listing_id) REFERENCES listings(id) ON DELETE CASCADE'),
        ('campaigns', 'campaigns_seller_id_fkey', 'FOREIGN KEY (seller_id) REFERENCES users(id)'),
        ('complaints', 'complaints_complained_user_id_fkey', 'FOREIGN KEY (complained_user_id) REFERENCES users(id)'),
        ('complaints', 'complaints_complainer_id_fkey', 'FOREIGN KEY (complainer_id) REFERENCES users(id)'),
        ('complaints', 'complaints_resolved_by_fkey', 'FOREIGN KEY (resolved_by) REFERENCES users(id)'),
        ('listing_views', 'listing_views_user_id_fkey', 'FOREIGN KEY (user_id) REFERENCES users(id)'),
        ('messages', 'messages_recipient_id_fkey', 'FOREIGN KEY (recipient_id) REFERENCES users(id)'),
        ('offers', 'offers_parent_offer_id_fkey', 'FOREIGN KEY (parent_offer_id) REFERENCES offers(id)'),
        ('payment', 'payment_from_user_id_fkey', 'FOREIGN KEY (from_user_id) REFERENCES users(id)'),
        ('payment', 'payment_to_user_id_fkey', 'FOREIGN KEY (to_user_id) REFERENCES users(id)'),
        ('seller_follows', 'seller_follows_followed_id_fkey', 'FOREIGN KEY (followed_id) REFERENCES users(id)'),
        ('vehicle_models', 'vehicle_models_vehicle_type_id_fkey', 'FOREIGN KEY (vehicle_type_id) REFERENCES vehicle_types(id)'),
        ('book_conditions', 'book_conditions_name_key', 'UNIQUE (name)'),
        ('book_formats', 'book_formats_name_key', 'UNIQUE (name)'),
        ('book_genres', 'book_genres_name_key', 'UNIQUE (name)'),
        ('book_languages', 'book_languages_name_key', 'UNIQUE (name)'),
        ('book_types', 'book_types_name_key', 'UNIQUE (name)'),
        ('clothing_brands', 'clothing_brands_name_key', 'UNIQUE (name)'),
        ('clothing_types', 'clothing_types_name_key', 'UNIQUE (name)'),
        ('seller_follows', 'uk_seller_follows_follower_followed', 'UNIQUE (follower_id, followed_id)'),
        ('sport_conditions', 'sport_conditions_name_key', 'UNIQUE (name)'),
        ('sport_disciplines', 'sport_disciplines_name_key', 'UNIQUE (name)'),
        ('sport_equipment_types', 'sport_equipment_types_name_key', 'UNIQUE (name)')
    ) AS v(table_name, constraint_name, definition) LOOP
        IF NOT EXISTS (SELECT 1 FROM pg_constraint
                       WHERE conrelid = r.table_name::regclass AND conname = r.constraint_name) THEN
            EXECUTE format('ALTER TABLE %I ADD CONSTRAINT %I %s', r.table_name, r.constraint_name, r.definition);
        END IF;
    END LOOP;
END $$;
